// @name Sudoku
// @background #f5f2ec
// @refresh 3600
// Sudoku for a touch screen: tap a cell, then a number on the pad. Notes mode
// pencils small candidates in instead, Erase clears a cell, Undo takes the last
// change back, Hint fills a cell and Check marks the wrong ones. Every puzzle
// is made on the frame and has exactly one solution; the game in progress is
// kept in the scene's state, so it outlasts a restart.
import { boxOf, conflicts, makePuzzle } from './logic'

// High contrast where the panel shows no color (black and white, greys), or
// when the scene's Contrast setting asks for it.
const highContrast = (app) => {
  const mode = app.state.contrast || 'auto'
  return mode === 'high' || (mode === 'auto' && app.frame.color === false)
}
// Color e-paper (a Spectra panel's six inks) on Auto: a white page, black
// ink and solid colors only, since greys and pale tints dither to confetti.
const inkPaper = (app) => (app.state.contrast || 'auto') === 'auto' && app.frame.paper === true && app.frame.color !== false
const themeOf = (app) => (highContrast(app) ? THEMES.high : inkPaper(app) ? THEMES.ink : THEMES.color)

const THEMES = {
  color: {
    page: 'bg-[#f5f2ec] text-[#26303b]',
    muted: 'text-[#6c7682]',
    title: 'text-[#26303b]',
    lines: 'bg-[#2e3f52]',
    thin: 'bg-[#9aa8b6]',
    cell: 'bg-[#fffdf9]',
    peer: 'bg-[#e8edf2]',
    same: 'bg-[#d5e6dd]',
    selected: 'bg-[#efc66f]',
    given: 'text-[#1d2731] font-bold',
    entry: 'text-[#1f6a8a] font-medium',
    selectedText: '',
    note: 'text-[#5d6b79]',
    error: 'bg-[#f6d6cf]',
    errorText: 'text-[#b33a26] font-bold',
    errorRing: '',
    key: 'bg-[#fffdf9] text-[#26303b] border-2 border-[#c9d1da] active:bg-[#e8edf2]',
    keyDone: 'bg-[#ece8e1] text-[#b2aca3]',
    doneDigit: '',
    keyCount: 'text-[#8a95a1]',
    tool: 'bg-[#e4ded4] text-[#26303b] active:bg-[#d6cfc3]',
    toolOn: 'bg-[#2e3f52] text-white',
    primary: 'bg-[#2f6b66] text-white active:bg-[#24524e]',
    card: 'bg-[#fffdf9] border-4 border-[#2e3f52] text-[#26303b]',
  },
  high: {
    page: 'bg-white text-black',
    muted: 'text-black',
    title: 'text-black',
    lines: 'bg-black',
    thin: 'bg-black',
    cell: 'bg-white',
    peer: 'bg-white',
    same: 'bg-white',
    selected: 'bg-black',
    given: 'text-black font-black',
    entry: 'text-black font-normal',
    selectedText: 'text-white',
    note: 'text-black',
    error: 'bg-white',
    errorText: 'text-black font-bold',
    errorRing: 'border-[3px] border-black rounded-full',
    key: 'bg-white text-black border-2 border-black',
    // A digit placed nine times: a thin frame and the digit struck through,
    // never a grey that dithers away.
    keyDone: 'bg-white text-black border border-black',
    doneDigit: 'line-through font-normal',
    keyCount: 'text-black',
    tool: 'bg-white text-black border-2 border-black',
    toolOn: 'bg-black text-white',
    primary: 'bg-black text-white',
    card: 'bg-white border-4 border-black text-black',
  },
  // Color e-paper: black lines and ink, the selected cell yellow, your digits
  // blue, the wrong ones red, New green.
  ink: {
    page: 'bg-white text-black',
    muted: 'text-black',
    title: 'text-black',
    lines: 'bg-black',
    thin: 'bg-black',
    cell: 'bg-white',
    peer: 'bg-white',
    same: 'bg-white',
    selected: 'bg-[#ffff00]',
    given: 'text-black font-bold',
    entry: 'text-[#0033cc] font-bold',
    selectedText: '',
    note: 'text-black',
    error: 'bg-white',
    errorText: 'text-[#cc0000] font-bold',
    errorRing: '',
    key: 'bg-white text-black border-2 border-black',
    keyDone: 'bg-white text-black border border-black',
    doneDigit: 'line-through font-normal',
    keyCount: 'text-black',
    tool: 'bg-white text-black border-2 border-black',
    toolOn: 'bg-black text-white',
    primary: 'bg-[#006b2e] text-white',
    card: 'bg-white border-4 border-black text-black',
  },
}

const DIFFICULTIES = { easy: 'Easy', medium: 'Medium', hard: 'Hard', expert: 'Expert' }
const difficultySetting = (app) => (DIFFICULTIES[app.state.difficulty] ? app.state.difficulty : 'medium')
const flag = (value, fallback) => (value === undefined || value === null || value === '' ? fallback : value === true || value === 'true')

const newGame = (difficulty) => {
  const seed = (Date.now() % 2147483647) ^ Math.floor(Math.random() * 1e9)
  const { puzzle, solution } = makePuzzle(difficulty, seed)
  return {
    difficulty,
    puzzle,
    solution,
    values: puzzle,
    notes: new Array(81).fill(0),
    start: Date.now(),
    end: 0,
    hints: 0,
    checked: false,
    undo: [],
  }
}

const isGame = (g) =>
  g && typeof g === 'object' && typeof g.puzzle === 'string' && g.puzzle.length === 81 &&
  typeof g.values === 'string' && g.values.length === 81 && typeof g.solution === 'string' && Array.isArray(g.notes)

/** The game in progress; a new one when there is none, or when the difficulty setting changed. */
const loadGame = (app) => {
  const difficulty = difficultySetting(app)
  const kept = app.state.game
  if (isGame(kept) && kept.difficulty === difficulty) return kept
  const game = newGame(difficulty)
  frameos.setState('game', game)
  frameos.remember('selected', -1)
  return game
}

const setAt = (text, i, digit) => text.slice(0, i) + digit + text.slice(i + 1)

/** Every change: the board before it goes on the undo list (the last 20), then the change, then save. */
const change = (game, fn) => {
  if (game.end) return
  const next = { ...game, notes: game.notes.slice(), checked: false }
  next.undo = [...(game.undo || []).slice(-19), { values: game.values, notes: game.notes }]
  if (fn(next) === false) return
  if (next.values === next.solution && !next.end) next.end = Date.now()
  frameos.setState('game', next)
  frameos.remember('note', '')
}

const isGiven = (game, i) => game.puzzle[i] !== '0'

const enter = (app, game, digit) => {
  const i = frameos.recall('selected') ?? -1
  if (i < 0 || isGiven(game, i)) return
  const notesMode = !!frameos.recall('notesMode')
  change(game, (g) => {
    if (notesMode) {
      if (g.values[i] !== '0') return false
      g.notes[i] ^= 1 << (digit - 1)
      return
    }
    const now = g.values[i] === String(digit) ? '0' : String(digit)
    g.values = setAt(g.values, i, now)
    g.notes[i] = 0
    if (now === '0') return
    // A placed digit leaves the notes of its row, column and box.
    const r = Math.floor(i / 9)
    const c = i % 9
    for (let k = 0; k < 81; k++) {
      if (Math.floor(k / 9) === r || k % 9 === c || boxOf(k) === boxOf(i)) g.notes[k] &= ~(1 << (digit - 1))
    }
  })
}

const erase = (game) => {
  const i = frameos.recall('selected') ?? -1
  if (i < 0 || isGiven(game, i)) return
  if (game.values[i] === '0' && !game.notes[i]) return
  change(game, (g) => {
    g.values = setAt(g.values, i, '0')
    g.notes[i] = 0
  })
}

const undoLast = (game): boolean => {
  const list = game.undo || []
  if (!list.length || game.end) return false
  const last = list[list.length - 1]
  frameos.setState('game', { ...game, values: last.values, notes: last.notes, undo: list.slice(0, -1), checked: false })
  frameos.remember('note', '')
  return true
}

/** Fills the selected cell when it is empty or wrong, else the first empty cell, with its answer. */
const hint = (game) => {
  let i = frameos.recall('selected') ?? -1
  if (i < 0 || isGiven(game, i) || game.values[i] === game.solution[i]) {
    i = game.values.indexOf('0')
    if (i < 0) for (let k = 0; k < 81; k++) if (game.values[k] !== game.solution[k]) { i = k; break }
  }
  if (i < 0) return
  frameos.remember('selected', i)
  change(game, (g) => {
    g.values = setAt(g.values, i, g.solution[i])
    g.notes[i] = 0
    g.hints = (g.hints || 0) + 1
  })
}

const check = (game) => {
  let wrong = 0
  let empty = 0
  for (let i = 0; i < 81; i++) {
    if (game.values[i] === '0') empty++
    else if (game.values[i] !== game.solution[i]) wrong++
  }
  frameos.setState('game', { ...game, checked: wrong > 0 })
  frameos.remember('note', wrong ? `${wrong} wrong ${wrong === 1 ? 'cell' : 'cells'} marked` : `No mistakes so far, ${empty} to go`)
}

const startOver = (app) => {
  frameos.remember('confirm', false)
  frameos.remember('selected', -1)
  frameos.remember('note', '')
  frameos.setState('game', newGame(difficultySetting(app)))
}

const askNewGame = (app, game) => {
  const touched = game.values !== game.puzzle
  if (!touched || game.end) startOver(app)
  else frameos.remember('confirm', true)
}

const minutes = (game) => {
  const ms = (game.end || Date.now()) - (game.start || Date.now())
  const m = Math.max(0, Math.floor(ms / 60000))
  return m >= 60 ? `${Math.floor(m / 60)} h ${m % 60} min` : `${m} min`
}

// What each cell shows, one signal a cell, the count left on each digit key,
// the Notes switch and the status line: a tap runs only the parts that read
// what it changed, not get(). The game itself stays in the scene's `game` field.
const looks = Array.from({ length: 81 }, () => signal(''))
const counts = Array.from({ length: 10 }, () => signal(9))
const notesOn = signal(false)
const noteLine = signal('')
const statusLine = signal('')
const wake = signal(0)
const tick = signal(0)

// Every signal from the game and what the frame remembers (the selected cell,
// the Notes switch, the last check's line).
const show = (app, game) => {
  const hc = highContrast(app)
  const t = themeOf(app)
  const showConflicts = flag(app.state.highlightConflicts, true)
  const showTimer = flag(app.state.showTimer, true)
  const selected = frameos.recall('selected') ?? -1
  // Pale tints dither into specks on e-paper: there only the selected cell is lit.
  const tints = !hc && app.frame.paper !== true
  const conflict = showConflicts ? conflicts(game.values) : null
  const selValue = selected >= 0 ? game.values[selected] : '0'
  const selRow = Math.floor(selected / 9)
  const selCol = selected % 9
  for (let i = 0; i < 81; i++) {
    const v = game.values[i]
    const given = isGiven(game, i)
    const wrong = (game.checked && !given && v !== '0' && v !== game.solution[i]) || (conflict && conflict[i] && !given)
    let cls = t.cell
    let textCls = given ? t.given : t.entry
    if (i === selected) {
      cls = t.selected
      textCls = `${textCls} ${t.selectedText}`
    } else if (wrong) {
      cls = t.error
    } else if (tints && selected >= 0 && v !== '0' && v === selValue) {
      cls = t.same
    } else if (tints && selected >= 0 && (Math.floor(i / 9) === selRow || i % 9 === selCol || boxOf(i) === boxOf(selected))) {
      cls = t.peer
    }
    if (wrong && i !== selected) textCls = t.errorText
    // In high contrast the cells with the selected digit get a ring too, and a wrong one a heavier one.
    let ring = ''
    if (hc && wrong) ring = t.errorRing
    else if (hc && i !== selected && selected >= 0 && v !== '0' && v === selValue) ring = 'border-2 border-black rounded-full'
    const noteCls = i === selected && hc ? 'text-white' : t.note
    looks[i].value = [v, game.notes[i] || 0, given ? 1 : 0, cls, textCls, ring, noteCls].join('|')
  }
  // The count of each digit still to place: a digit placed nine times dims on the pad.
  const left = new Array(10).fill(9)
  for (let i = 0; i < 81; i++) left[game.values.charCodeAt(i) - 48]--
  for (let d = 1; d <= 9; d++) counts[d].value = left[d]
  notesOn.value = !!frameos.recall('notesMode')
  noteLine.value = frameos.recall('note') || ''
  statusLine.value = [DIFFICULTIES[game.difficulty], showTimer ? minutes(game) : '', game.hints ? `${game.hints} ${game.hints === 1 ? 'hint' : 'hints'}` : '']
    .filter(Boolean)
    .join(' · ')
  // On a screen that shows changes at once, the minutes tick while a game is on.
  wake.value = showTimer && !game.end && app.frame.fast ? 60 - (Math.floor((Date.now() - game.start) / 1000) % 60) : 0
  tick.value = tick.peek() + 1
}

// The card over the board (asking for a new puzzle, or saying it is solved).
const overlayOf = (app) => (frameos.recall('confirm') ? 'confirm' : loadGame(app).end ? 'solved' : '')

// A tap that changes the game or the selection: the change, then the signals.
// One that brings the card over the board or takes it away sets no signal:
// get() draws it whole.
const act = (app, fn) => {
  const before = overlayOf(app)
  fn(loadGame(app))
  if (overlayOf(app) === before) show(app, loadGame(app))
}

// Keys on a keyboard: arrows move, digits fill, Backspace / Delete / 0 erase,
// n notes, u undo, h hint.
export function onEvent(app, context) {
  const game = loadGame(app)
  const p = context.payload || {}
  // The frame's back closes the "New puzzle?" question, else takes back the
  // last entry; with nothing to take back it is the frame's.
  if (context.event === 'back') {
    if (frameos.recall('confirm')) {
      frameos.remember('confirm', false)
      return true
    }
    return undoLast(game)
  }
  if (context.event !== 'keyDown' || p.ctrl || p.alt || p.meta) return false
  const key = String(p.key || '')
  if (frameos.recall('confirm')) {
    if (key === 'Enter' || key === 'y') startOver(app)
    else if (key === 'Escape' || key === 'n') frameos.remember('confirm', false)
    else return false
    return true
  }
  const selected = frameos.recall('selected') ?? -1
  const moves = { ArrowLeft: -1, ArrowRight: 1, ArrowUp: -9, ArrowDown: 9 }
  if (moves[key] !== undefined) {
    const from = selected < 0 ? 40 : selected
    const r = Math.floor(from / 9)
    const c = from % 9
    const nr = (r + (key === 'ArrowUp' ? 8 : key === 'ArrowDown' ? 1 : 0)) % 9
    const nc = (c + (key === 'ArrowLeft' ? 8 : key === 'ArrowRight' ? 1 : 0)) % 9
    frameos.remember('selected', selected < 0 ? 40 : nr * 9 + nc)
    return true
  }
  if (key >= '1' && key <= '9') enter(app, game, Number(key))
  else if (key === '0' || key === 'Backspace' || key === 'Delete') erase(game)
  else if (key === 'n') frameos.remember('notesMode', !frameos.recall('notesMode'))
  else if (key === 'u') undoLast(game)
  else if (key === 'h') hint(game)
  else return false
  return true
}

// One cell: a digit, or its notes as a 3x3 of small digits.
const Cell = memo(({ i, px, font, noteFont, app }) => {
  const [value, noteBits, given, cls, textCls, ring, noteCls] = looks[i].value.split('|')
  const notes = Number(noteBits)
  const select = () => act(app, () => frameos.remember('selected', i))
  if (value !== '0') {
    const digit = <span className={`text-[${given === '1' ? font : Math.round(font * 0.95)}px] leading-none ${textCls}`}>{value}</span>
    const ringPx = Math.round(px * 0.78)
    return (
      <div className={`w-[${px}px] h-[${px}px] flex items-center justify-center ${cls}`} onClick={select}>
        {ring ? <div className={`w-[${ringPx}px] h-[${ringPx}px] flex items-center justify-center ${ring}`}>{digit}</div> : digit}
      </div>
    )
  }
  if (!notes) return <div className={`w-[${px}px] h-[${px}px] ${cls}`} onClick={select} />
  const third = Math.floor(px / 3)
  const rows = []
  for (let r = 0; r < 3; r++) {
    const row = []
    for (let c = 0; c < 3; c++) {
      const d = r * 3 + c + 1
      row.push(
        <div className={`w-[${third}px] h-[${third}px] flex items-center justify-center text-[${noteFont}px] leading-none ${noteCls}`}>
          {notes & (1 << (d - 1)) ? d : ''}
        </div>,
      )
    }
    rows.push(<div className="flex">{row}</div>)
  }
  return (
    <div className={`w-[${px}px] h-[${px}px] flex flex-col items-center justify-center ${cls}`} onClick={select}>
      {rows}
    </div>
  )
})

// The status line: the check's line, else the difficulty, the minutes and the
// hints. It runs on every render (it reads `tick`), partial ones included, so
// it is what asks for the next minute while they tick.
const Status = memo(({ className, slim }) => {
  tick.value
  if (wake.value) frameos.setNextSleep(wake.value)
  const text = noteLine.value || (slim ? `Sudoku · ${statusLine.value}` : statusLine.value)
  return slim ? <div className={className}>{text}</div> : <span className={className}>{text}</span>
})

const Tool = ({ label, onClick, cls, w, rowH, toolFont }) => (
  <div className={`${w ? `w-[${w}px]` : 'flex-1'} h-[${rowH}px] rounded-xl flex items-center justify-center whitespace-nowrap text-[${toolFont}px] font-bold ${cls}`} onClick={onClick}>
    {label}
  </div>
)

// `brief`: a key too narrow for "Notes on" says Notes, lit while it is on.
const NotesTool = memo(({ t, rowH, toolFont, app, brief }) => {
  const on = notesOn.value
  return (
    <Tool label={on && !brief ? 'Notes on' : 'Notes'} onClick={() => act(app, () => frameos.remember('notesMode', !on))}
      cls={on ? t.toolOn : t.tool} w={0} rowH={rowH} toolFont={toolFont} />
  )
})

// The Notes switch as a round key, lit while it is on.
const RoundNotes = memo(({ t, app, x, y, d, font }) => {
  const on = notesOn.value
  return (
    <div className={`absolute left-[${x}px] top-[${y}px] w-[${d}px] h-[${d}px] rounded-full flex items-center justify-center text-[${font}px] font-bold ${on ? t.toolOn : t.tool}`}
      onClick={() => act(app, () => frameos.remember('notesMode', !on))}>
      Notes
    </div>
  )
})

const DigitKey = memo(({ d, w, h, t, app }) => {
  const left = counts[d].value
  // "5 left" under the digit where the key has room for it at 11 px or more
  // (14 on color e-paper, whose dither eats small type).
  const countFont = Math.min(Math.round(h * 0.2), Math.floor((w - 4) / 3.3))
  const countMin = t === THEMES.ink ? 14 : 11
  return (
    <div className={`w-[${w}px] h-[${h}px] rounded-xl flex flex-col items-center justify-center ${left <= 0 ? t.keyDone : t.key}`}
      onClick={() => act(app, (game) => enter(app, game, d))}>
      <span className={`text-[${Math.round(Math.min(h * 0.55, w * 0.6))}px] font-bold leading-none ${left <= 0 ? t.doneDigit : ''}`}>{d}</span>
      {h >= 56 && countFont >= countMin && left > 0 ? <span className={`text-[${countFont}px] font-semibold leading-none mt-1 ${t.keyCount}`}>{`${left} left`}</span> : null}
    </div>
  )
})

export function get(app, context) {
  const W = context.imageWidth ?? app.frame.width
  const H = context.imageHeight ?? app.frame.height
  const t = themeOf(app)
  const game = loadGame(app)
  const confirm = !!frameos.recall('confirm')
  const solved = !!game.end
  show(app, game)

  // A round panel: the board in the square inside the circle, the digits in
  // the arcs above and below it, the tools down its two sides.
  const round = context.round === true
  const rim = Math.min(W, H) / 2 - 12
  const m = Math.round(Math.min(W, H) * 0.04)
  const wide = W >= H * 1.2
  const rowH = Math.round(Math.max(wide ? 34 : 44, Math.min(H * (wide ? 0.13 : 0.075), 96)))
  // Stacked: a title row where there is room for one, else a slim status line.
  const headerH = wide ? 0 : H >= W * 1.25 ? Math.round(rowH * 0.8) : 22
  // Stacked on a narrow panel (a watch): the six tools still in one row, in
  // smaller type, and the rows and the spacing tighter, so the board gets
  // the room (two rows of tools left it 140 px).
  const rowW = W - 2 * m
  const narrow = !wide && (rowW - 5 * 6) / 6 < 2.95 * 14 + 8
  const sgap = narrow ? 4 : Math.round(m * 0.6)
  const sy = narrow ? Math.min(m, 6) : m
  const digitH = narrow ? Math.round(Math.max(32, Math.min(H * 0.12, rowH))) : rowH
  const toolH = narrow ? Math.round(Math.max(28, Math.min(H * 0.1, rowH))) : rowH
  const rowGap = narrow ? 3 : 6
  // Wide: the board and a column beside it. A column wider than it is tall
  // (a strip of a panel) takes the nine digits in a row and the six tools in
  // another; else the digits are a 3x3 pad over two rows of three tools, and
  // the column keeps room for three keys a finger wide.
  const wgap = Math.round(m * 0.5)
  const strip = wide && W - 3 * m - Math.min(H - 2 * m, (W - 3 * m) * 0.63) >= (H - 2 * m) * 1.3
  const minKeyW = Math.round(Math.max(34, Math.min(H * 0.15, 48)))
  const avail = round
    ? Math.floor(rim * Math.SQRT2) - 16
    : wide
      ? Math.min(H - 2 * m, (W - 3 * m) * 0.63, strip ? W : W - 3 * m - 3 * minKeyW - 2 * wgap)
      : Math.min(W - 2 * m, H - 2 * sy - headerH - digitH - toolH - 3 * sgap)
  const thick = Math.max(3, Math.round(avail * 0.008))
  const thin = Math.max(1, Math.round(avail * 0.0025))
  const cell = Math.floor((avail - 4 * thick - 6 * thin) / 9)
  const board = cell * 9 + 4 * thick + 6 * thin
  // Small cells get bigger digits for their size.
  const font = Math.round(cell * (cell < 26 ? 0.72 : 0.6))
  const noteFont = Math.max(9, Math.round(cell * 0.27))

  const cellOf = (i) => <Cell i={i} px={cell} font={font} noteFont={noteFont} app={app} />

  const boxes = []
  for (let br = 0; br < 3; br++) {
    const bandBoxes = []
    for (let bc = 0; bc < 3; bc++) {
      const rows = []
      for (let r = 0; r < 3; r++) {
        const cells = []
        for (let c = 0; c < 3; c++) cells.push(cellOf((br * 3 + r) * 9 + bc * 3 + c))
        rows.push(<div className={`flex gap-[${thin}px]`}>{cells}</div>)
      }
      bandBoxes.push(<div className={`flex flex-col gap-[${thin}px] ${t.thin}`}>{rows}</div>)
    }
    boxes.push(<div className={`flex gap-[${thick}px]`}>{bandBoxes}</div>)
  }

  const inset = Math.round(board * 0.07)
  const cardFont = Math.round(Math.max(16, Math.min(board * 0.05, 30)))
  const cardButton = (label, cls, onClick) => (
    <div className={`h-[${Math.max(48, Math.round(board * 0.12))}px] px-4 rounded-xl flex items-center whitespace-nowrap text-[${cardFont}px] font-bold ${cls}`} onClick={onClick}>
      {label}
    </div>
  )
  const card = (title, line, buttons) => (
    <div className={`absolute left-[${inset}px] right-[${inset}px] top-[${Math.round(board * 0.24)}px] rounded-2xl p-[${Math.round(board * 0.045)}px] flex flex-col items-center gap-3 ${t.card}`}>
      <span className={`text-[${Math.round(board * 0.085)}px] font-bold text-center`}>{title}</span>
      <span className={`text-[${Math.round(Math.max(16, board * 0.042))}px] text-center`}>{line}</span>
      <div className="flex gap-3">{buttons}</div>
    </div>
  )
  let overlay = null
  if (confirm) {
    overlay = card('New puzzle?', 'The puzzle in progress will be lost.', [
      cardButton('Cancel', t.tool, () => frameos.remember('confirm', false)),
      cardButton('New puzzle', t.primary, () => startOver(app)),
    ])
  } else if (solved) {
    const hints = game.hints ? `, ${game.hints} ${game.hints === 1 ? 'hint' : 'hints'}` : ''
    overlay = card('Solved!', `${DIFFICULTIES[game.difficulty]} in ${minutes(game)}${hints}.`, [
      cardButton('New puzzle', t.primary, () => startOver(app)),
    ])
  }

  const boardBox = (
    <div className={`relative w-[${board}px] h-[${board}px] shrink-0 flex flex-col gap-[${thick}px] p-[${thick}px] ${t.lines}`}>
      {boxes}
      {overlay}
    </div>
  )

  // How wide a tool key is in this arrangement, and its words no wider:
  // "Notes", "Erase" and "Check" are about 2.9 em of bold type.
  const panelW = W - board - 3 * m
  const toolW = wide ? (strip ? (panelW - 5 * wgap) / 6 : (panelW - 2 * wgap) / 3) : (rowW - 5 * rowGap) / 6
  const toolFont = Math.max(10, Math.min(Math.round(Math.max(15, Math.min(rowH * 0.32, 26))), Math.floor((toolW - (narrow ? 4 : 8)) / 2.95)))
  const toolRowH = strip ? Math.round(Math.max(rowH, Math.min((H - 2 * m) * 0.2, 56))) : wide ? rowH : toolH
  // The buttons read the game when they are pressed: after a partial render
  // the game get() saw is not the game any more.
  const tool = (label, onClick, cls = t.tool, w = 0) => <Tool label={label} onClick={onClick} cls={cls} w={w} rowH={toolRowH} toolFont={toolFont} />
  const digitKey = (d, w, h) => <DigitKey d={d} w={w} h={h} t={t} app={app} />
  const tools = [
    <NotesTool t={t} rowH={toolRowH} toolFont={toolFont} app={app} brief={toolW - 8 < 4.31 * toolFont} />,
    tool('Erase', () => act(app, erase)),
    tool('Undo', () => act(app, undoLast)),
  ]

  if (round) {
    // How wide a row may be `dy` px above or below the middle.
    const chord = (dy) => Math.floor(2 * Math.sqrt(Math.max(0, rim * rim - dy * dy)))
    const top = Math.round((H - board) / 2)
    const left = Math.round((W - board) / 2)
    const gap = 5
    const keyH = Math.max(36, Math.round(board * 0.13))
    // A row of digit keys `keyH` tall, its edge nearest the rim `dy` from the middle.
    const digitRow = (digits, y, dy) => {
      const keyW = Math.min(Math.round(keyH * 1.35), Math.floor((chord(dy) - gap * (digits.length - 1)) / digits.length))
      return (
        <div className={`absolute left-0 top-[${y}px] w-[${W}px] flex justify-center gap-[${gap}px]`}>
          {digits.map((d) => digitKey(d, keyW, keyH))}
        </div>
      )
    }
    const upperY = top - gap - keyH
    const lowerY = top + board + gap
    const statusFont = Math.max(14, Math.round(board * 0.048))
    const statusH = Math.round(statusFont * 1.3)
    const statusY = upperY - 2 - statusH
    // The tools: round keys stacked in the room left and right of the board.
    const sideW = left
    const keyD = Math.min(56, Math.max(44, sideW - 22))
    const keyFont = Math.max(14, Math.round(keyD * 0.27))
    const sideKey = (label, onClick, cls, x, y) => (
      <div className={`absolute left-[${x}px] top-[${y}px] w-[${keyD}px] h-[${keyD}px] rounded-full flex items-center justify-center text-[${keyFont}px] font-bold ${cls}`} onClick={onClick}>
        {label}
      </div>
    )
    const step = keyD + 8
    const ys = [-1, 0, 1].map((k) => Math.round(H / 2 + k * step - keyD / 2))
    const leftX = left - 6 - keyD
    const rightX = left + board + 6
    return (
      <div className={`relative w-[${W}px] h-[${H}px] ${t.page}`}>
        <div className={`absolute left-[${left}px] top-[${top}px]`}>{boardBox}</div>
        <div className={`absolute left-0 top-[${statusY}px] w-[${W}px] h-[${statusH}px] flex items-center justify-center`}>
          <Status className={`max-w-[${chord(H / 2 - statusY)}px] text-[${statusFont}px] truncate ${t.muted}`} slim={false} />
        </div>
        {digitRow([1, 2, 3, 4, 5], upperY, H / 2 - upperY)}
        {digitRow([6, 7, 8, 9], lowerY, lowerY + keyH - H / 2)}
        <RoundNotes t={t} app={app} x={leftX} y={ys[0]} d={keyD} font={keyFont} />
        {sideKey('Erase', () => act(app, erase), t.tool, leftX, ys[1])}
        {sideKey('Undo', () => act(app, undoLast), t.tool, leftX, ys[2])}
        {sideKey('Hint', () => act(app, hint), t.tool, rightX, ys[0])}
        {sideKey('Check', () => act(app, check), t.tool, rightX, ys[1])}
        {sideKey('New', () => act(app, (game) => askNewGame(app, game)), t.primary, rightX, ys[2])}
      </div>
    )
  }

  if (wide) {
    const gap = wgap
    const colH = H - 2 * m
    const rest = [tools, tool('Hint', () => act(app, hint)), tool('Check', () => act(app, check)), tool('New', () => act(app, (game) => askNewGame(app, game)), t.primary)]
    // A column too short for the title over the pad keeps the status line alone.
    const titled = strip || colH >= 250
    const titleFont = Math.round(Math.min(rowH * 0.6, panelW * 0.13))
    const statusFont = Math.round(Math.min(Math.max(15, rowH * 0.28), panelW / 7.2))
    const titleH = titled ? Math.round(titleFont * 1.25 + statusFont * 1.3) : Math.round(statusFont * 1.3)
    const heading = (
      <div className="flex flex-col">
        {titled ? <span className={`text-[${titleFont}px] font-bold leading-tight ${t.title}`}>Sudoku</span> : null}
        <Status className={`text-[${statusFont}px] truncate ${t.muted}`} slim={false} />
      </div>
    )
    if (strip) {
      // The nine digits in a row over the six tools, under the title.
      const keyW = Math.floor((panelW - 8 * gap) / 9)
      const keyH = Math.round(Math.max(36, Math.min(keyW * 1.3, colH - titleH - toolRowH - 4 * gap)))
      return (
        <div className={`flex w-full h-full p-[${m}px] gap-[${m}px] items-center ${t.page}`}>
          {boardBox}
          <div className={`flex-1 h-full flex flex-col justify-between gap-[${gap}px]`}>
            {heading}
            <div className={`flex flex-col gap-[${2 * gap}px]`}>
              <div className={`flex gap-[${gap}px]`}>{[1, 2, 3, 4, 5, 6, 7, 8, 9].map((d) => digitKey(d, keyW, keyH))}</div>
              <div className={`flex gap-[${gap}px]`}>{rest}</div>
            </div>
          </div>
        </div>
      )
    }
    const keyW = Math.floor((panelW - 2 * gap) / 3)
    // The pad takes what the title and the two rows of tools leave.
    const room = Math.floor((colH - titleH - 2 * rowH - 5 * gap) / 3)
    const keyH = Math.min(room, Math.round(Math.max(48, Math.min(keyW * 0.8, room))))
    const pad = []
    for (let r = 0; r < 3; r++) {
      pad.push(<div className={`flex gap-[${gap}px]`}>{[1, 2, 3].map((c) => digitKey(r * 3 + c, keyW, keyH))}</div>)
    }
    return (
      <div className={`flex w-full h-full p-[${m}px] gap-[${m}px] items-center ${t.page}`}>
        {boardBox}
        <div className={`flex-1 h-full flex flex-col justify-between gap-[${gap}px]`}>
          {heading}
          <div className={`flex flex-col gap-[${gap}px]`}>{pad}</div>
          <div className={`flex gap-[${gap}px]`}>{tools}</div>
          <div className={`flex gap-[${gap}px]`}>{rest.slice(1)}</div>
        </div>
      </div>
    )
  }

  // Stacked: the board, a row of nine digits, a row of tools (two on a
  // narrow panel), as wide as the screen allows.
  const keyW = Math.floor((rowW - 8 * rowGap) / 9)
  const more = [tool('Hint', () => act(app, hint)), tool('Check', () => act(app, check)), tool('New', () => act(app, (game) => askNewGame(app, game)), t.primary)]
  return (
    <div className={`flex flex-col w-full h-full px-[${m}px] py-[${sy}px] gap-[${sgap}px] items-center justify-center ${t.page}`}>
      {headerH > 22 ? (
        <div className={`flex w-[${board}px] h-[${headerH}px] items-center justify-between`}>
          <span className={`text-[${Math.round(headerH * 0.6)}px] font-bold ${t.title}`}>Sudoku</span>
          <Status className={`text-[${Math.round(Math.max(15, headerH * 0.3))}px] truncate ${t.muted}`} slim={false} />
        </div>
      ) : (
        <Status className={`flex w-[${rowW}px] h-[${headerH}px] items-center justify-center text-[15px] truncate ${t.muted}`} slim />
      )}
      {boardBox}
      <div className={`flex gap-[${rowGap}px] w-[${rowW}px]`}>{[1, 2, 3, 4, 5, 6, 7, 8, 9].map((d) => digitKey(d, keyW, digitH))}</div>
      <div className={`flex gap-[${rowGap}px] w-[${rowW}px]`}>
        {tools}
        {more}
      </div>
    </div>
  )
}

