// Sudoku without drawing: making puzzles with one solution, and the rules a
// game needs. Grids are 81 cells, row by row; strings of digits ("0" for an
// empty cell) where they are kept in state, Uint8Arrays while working.

// How many clues each difficulty leaves. Clues are taken away in pairs (a
// cell and its mirror through the centre) while the puzzle keeps exactly one
// solution, so "expert" ends at the fewest the passes can reach, often 24-26.
export const CLUES = { easy: 40, medium: 33, hard: 28, expert: 24 }

/** mulberry32: small and fast, its whole state one integer. */
export function makeRandom(seed: number) {
  let s = seed | 0
  return () => {
    s = (s + 0x6d2b79f5) | 0
    let t = Math.imul(s ^ (s >>> 15), s | 1)
    t ^= t + Math.imul(t ^ (t >>> 7), t | 61)
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296
  }
}

function shuffled(list: number[], random: () => number): number[] {
  const out = list.slice()
  for (let i = out.length - 1; i > 0; i--) {
    const j = Math.floor(random() * (i + 1))
    const swap = out[i]
    out[i] = out[j]
    out[j] = swap
  }
  return out
}

/**
 * A full, valid grid: one known solution with its digits, rows within each
 * band, the bands, columns within each stack and the stacks shuffled, and
 * sometimes turned over its diagonal. Every one of those keeps a grid valid,
 * and together they give about 3 billion different grids, at no search cost.
 */
export function solvedGrid(random: () => number): Uint8Array {
  const digits = shuffled([1, 2, 3, 4, 5, 6, 7, 8, 9], random)
  const order = (): number[] => {
    const out: number[] = []
    for (const group of shuffled([0, 1, 2], random)) for (const k of shuffled([0, 1, 2], random)) out.push(group * 3 + k)
    return out
  }
  const rows = order()
  const cols = order()
  const flip = random() < 0.5
  const grid = new Uint8Array(81)
  for (let r = 0; r < 9; r++) {
    for (let c = 0; c < 9; c++) {
      const rr = rows[r]
      const cc = cols[c]
      // The base pattern: row r is row 0 shifted by 3*(r%3) + floor(r/3).
      const base = (3 * (rr % 3) + Math.floor(rr / 3) + cc) % 9
      grid[flip ? c * 9 + r : r * 9 + c] = digits[base]
    }
  }
  return grid
}

// Popcount of a 9-bit candidate mask, and the box of each cell.
const BITS = new Uint8Array(512)
for (let m = 1; m < 512; m++) BITS[m] = (m & 1) + BITS[m >> 1]
const BOX = new Uint8Array(81)
for (let i = 0; i < 81; i++) BOX[i] = Math.floor(Math.floor(i / 9) / 3) * 3 + Math.floor((i % 9) / 3)

/**
 * How many solutions the grid has, counting no further than `limit`. Returns
 * -1 when the search took more than `cap` steps (treat that as "not sure").
 * Backtracking on bitmasks, always at the cell with the fewest candidates.
 */
export function countSolutions(cells: Uint8Array, limit: number, cap: number): number {
  const rows = new Int32Array(9)
  const cols = new Int32Array(9)
  const boxes = new Int32Array(9)
  const empties: number[] = []
  for (let i = 0; i < 81; i++) {
    const v = cells[i]
    if (!v) {
      empties.push(i)
      continue
    }
    const bit = 1 << (v - 1)
    const r = (i / 9) | 0
    const c = i % 9
    if (rows[r] & bit || cols[c] & bit || boxes[BOX[i]] & bit) return 0
    rows[r] |= bit
    cols[c] |= bit
    boxes[BOX[i]] |= bit
  }
  const n = empties.length
  let found = 0
  let steps = 0
  // Backtracking, one level per empty cell, kept in arrays rather than in
  // nested calls: QuickJS takes a C stack frame per JS call, and the 50-odd
  // levels of a medium puzzle overflowed the 20 KB of stack an ESP32 gives it
  // (the reTerminal Sticky, 2026-11-25: Sudoku never drew there).
  const swapped = new Int32Array(n) // where the cell tried at each level came from
  const left = new Int32Array(n) // the candidates not tried yet at each level
  const placed = new Int32Array(n) // the candidate in place at each level
  let depth = 0
  let entering = true
  let stop = false // what the level just left said: stop searching
  while (depth >= 0) {
    if (entering) {
      if (depth === n) {
        found++
        stop = found >= limit
        entering = false
        depth--
        continue
      }
      if (++steps > cap) {
        stop = true
        entering = false
        depth--
        continue
      }
      // The empty cell (from depth on) with the fewest candidates goes first.
      let best = depth
      let bestMask = 0
      let bestCount = 10
      for (let k = depth; k < n; k++) {
        const i = empties[k]
        const mask = ~(rows[(i / 9) | 0] | cols[i % 9] | boxes[BOX[i]]) & 511
        const count = BITS[mask]
        if (count < bestCount) {
          best = k
          bestMask = mask
          bestCount = count
          if (count <= 1) break
        }
      }
      if (bestCount === 0) {
        stop = false
        entering = false
        depth--
        continue
      }
      const cell = empties[best]
      empties[best] = empties[depth]
      empties[depth] = cell
      swapped[depth] = best
      left[depth] = bestMask
      placed[depth] = 0
    } else {
      // Back from the level below: take this level's candidate away.
      const cell = empties[depth]
      const bit = placed[depth]
      rows[(cell / 9) | 0] ^= bit
      cols[cell % 9] ^= bit
      boxes[BOX[cell]] ^= bit
      if (stop) {
        empties[depth] = empties[swapped[depth]]
        empties[swapped[depth]] = cell
        depth--
        continue
      }
    }
    const cell = empties[depth]
    const mask = left[depth]
    if (!mask) {
      empties[depth] = empties[swapped[depth]]
      empties[swapped[depth]] = cell
      stop = false
      entering = false
      depth--
      continue
    }
    const bit = mask & -mask
    left[depth] = mask ^ bit
    placed[depth] = bit
    rows[(cell / 9) | 0] |= bit
    cols[cell % 9] |= bit
    boxes[BOX[cell]] |= bit
    depth++
    entering = true
  }
  return steps > cap ? -1 : found
}

/** Takes clues away from a full grid while the solution stays unique: mirrored pairs first, then single cells. */
function carve(solution: Uint8Array, target: number, random: () => number): Uint8Array {
  const cells = solution.slice()
  let clues = 81
  const tryRemove = (i: number, j: number) => {
    const size = i === j ? 1 : 2
    if (!cells[i] || !cells[j] || clues - size < target) return
    const a = cells[i]
    const b = cells[j]
    cells[i] = 0
    cells[j] = 0
    if (countSolutions(cells, 2, 4000) === 1) clues -= size
    else {
      cells[i] = a
      cells[j] = b
    }
  }
  for (const i of shuffled(Array.from({ length: 41 }, (_, k) => k), random)) {
    if (clues <= target) break
    tryRemove(i, 80 - i)
  }
  for (const i of shuffled(Array.from({ length: 81 }, (_, k) => k), random)) {
    if (clues <= target) break
    tryRemove(i, i)
  }
  return cells
}

function clueCount(cells: Uint8Array): number {
  let n = 0
  for (let i = 0; i < 81; i++) if (cells[i]) n++
  return n
}

/**
 * A puzzle with exactly one solution: a shuffled full grid, then clues taken
 * away, each removal kept only when the solution stays unique (a bounded
 * search; an unsure one keeps the clue). Hard and expert try a few grids and
 * keep the one that got closest to their number of clues.
 */
export function makePuzzle(difficulty: string, seed: number): { puzzle: string; solution: string; clues: number } {
  const random = makeRandom(seed)
  const target = CLUES[difficulty] || CLUES.medium
  const tries = difficulty === 'expert' ? 3 : difficulty === 'hard' ? 2 : 1
  let best: Uint8Array | null = null
  let bestSolution: Uint8Array | null = null
  for (let t = 0; t < tries; t++) {
    const solution = solvedGrid(random)
    const cells = carve(solution, target, random)
    if (!best || clueCount(cells) < clueCount(best)) {
      best = cells
      bestSolution = solution
    }
    if (clueCount(best) <= target) break
  }
  return { puzzle: toText(best), solution: toText(bestSolution), clues: clueCount(best) }
}

export function toText(cells: Uint8Array | number[]): string {
  let out = ''
  for (let i = 0; i < 81; i++) out += cells[i] || 0
  return out
}

/** The cells (row, column, box) that share a unit with cell i, i left out. */
export function peers(i: number): number[] {
  const r = (i / 9) | 0
  const c = i % 9
  const out: number[] = []
  for (let k = 0; k < 81; k++) {
    if (k === i) continue
    if (((k / 9) | 0) === r || k % 9 === c || BOX[k] === BOX[i]) out.push(k)
  }
  return out
}

/** Which cells hold a digit that another cell of their row, column or box holds too. */
export function conflicts(values: string): boolean[] {
  const out = new Array(81).fill(false)
  for (let i = 0; i < 81; i++) {
    const v = values.charCodeAt(i) - 48
    if (!v) continue
    const r = (i / 9) | 0
    const c = i % 9
    for (let k = i + 1; k < 81; k++) {
      if (values.charCodeAt(k) - 48 !== v) continue
      if (((k / 9) | 0) === r || k % 9 === c || BOX[k] === BOX[i]) {
        out[i] = true
        out[k] = true
      }
    }
  }
  return out
}

export function boxOf(i: number): number {
  return BOX[i]
}
